module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);
    wire not_S0, not_S1;
    wire term0, term1, term2, term3;

    not(not_S0, sel[0]);
    not(not_S1, sel[1]);

    and(term0, in[0], not_S1, not_S0);
    and(term1, in[1], not_S1, sel[0]);
    and(term2, in[2], sel[1], not_S0);
    and(term3, in[3], sel[1], sel[0]);

    or(out, term0, term1, term2, term3);
endmodule

