module mux4to1 (
    input [3:0] in,
    input [1:0] sel,
    output out
);

    wire not_s0, not_s1;
    wire term0, term1, term2, term3;

    // Invert select signals
    not (not_s0, sel[0]);
    not (not_s1, sel[1]);

    // Generate AND terms for each input
    and (term0, in[0], not_s1, not_s0);
    and (term1, in[1], not_s1, sel[0]);
    and (term2, in[2], sel[1], not_s0);
    and (term3, in[3], sel[1], sel[0]);

    // Combine all terms to get output
    or (out, term0, term1, term2, term3);

endmodule

