module decoder_2to4 (
    input [1:0] in,
    output [3:0] out
);

    wire not_key0, not_key1;

    // Invert the input bits
    not (not_key0, in[0]);
    not (not_key1, in[1]);

    // Generate each output using AND gates
    and (out[0], not_key1, not_key0);
    and (out[1], not_key1, in[0]);
    and (out[2], in[1], not_key0);
    and (out[3], in[1], in[0]);

endmodule

