module traffic_light (
    input clk, reset,
    output [2:0] light
);

reg [2:0] state_reg;
wire [2:0] D;

// D input logic
wire D0, D1, D2;
assign D0 = ~state_reg[2] & ~state_reg[1];
assign D1 = ~state_reg[2] & state_reg[1];
assign D2 = state_reg[2] & ~state_reg[1];
assign D = {D2, D1, D0};

// State register with synchronous reset
always @(posedge clk) begin
    if (reset)
        state_reg <= 3'b000;
    else
        state_reg <= D;
end

// Output logic
assign light[0] = ~state_reg[2] & ~state_reg[1] & state_reg[0];
assign light[1] = state_reg[2] & ~state_reg[1] & ~state_reg[0];
assign light[2] = state_reg[2] & state_reg[1] & ~state_reg[0];

endmodule

module traffic_light (
    input clk, reset,
    output [2:0] light
);

    // Define states with 3-bit encoding
    localparam [2:0] stateA = 3'b001,
                     stateB = 3'b010,
                     stateC = 3'b100;

    reg [2:0] current_state, next_state;

    // State register update with synchronous reset
    always @(posedge clk) begin
        if (reset)
            current_state <= stateA;
        else
            current_state <= next_state;
    end

    // Next state logic
    always @(*) begin
        case (current_state)
            stateA: next_state = stateB;
            stateB: next_state = stateC;
            stateC: next_state = stateA;
            default: next_state = stateA; // Handle unexpected states
        endcase
    end

    // Output logic based on current state
    assign light = current_state;

endmodule

