module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    parameter S0 = 2'b00,
              S1 = 2'b01,
              S2 = 2'b10,
              S3 = 2'b11;

    reg [1:0] state_reg, next_state;

    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state_reg <= S0;
        end else begin
            state_reg <= next_state;
        end
    end

    always @(*) begin
        case (state_reg)
            S0: next_state = up_request ? S1 : S0;
            S1: next_state = up_request ? S2 : S0;
            S2: next_state = down_request ? S3 : S2;
            S3: next_state = down_request ? S0 : S2;
            default: next_state = S0;
        endcase
    end

    assign state = state_reg;

endmodule

module elevator_controller (
