always @(*) begin
    case (current_state)
        STATE0: next_state = up_request ? STATE1 : STATE0;
        STATE1: begin
            if (!down_request)
                next_state = STATE2;
            else if (up_request)
                next_state = STATE1;
            else
                next_state = STATE0;
        end
        STATE2: next_state = up_request ? STATE2 : STATE0;
        default: next_state = STATE0;
    endcase
end

assign state = current_state;

endmodule

module elevator_controller (
    input clk, reset,
    input up_request, down_request,
    output [1:0] state
);

    // State encoding parameters
    localparam [1:0] Y0 = 2'b00,
                     Y1 = 2'b01,
                     Y2 = 2'b10;

    reg [1:0] state_reg, next_state;

    // State register with synchronous reset
    always @(posedge clk or posedge reset) begin
        if (reset)
            state_reg <= Y0;
        else
            state_reg <= next_state;
    end

    // Next state combinational logic
    always @(*) begin
        case (state_reg)
            Y0: next_state = up_request ? Y1 : Y0;
            Y1: next_state = (up_request & down_request) ? Y2 : Y1;
            Y2: begin
                if (down_request)
                    next_state = Y2;
                else
                    next_state = (up_request == 0) ? Y0 : Y2;
            end
            default: next_state = Y0;
        endcase
    end

    // Output assignment
    assign state = state_reg;

endmodule

