module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

localparam [1:0] RESET_STATE = 2'b00,
                 WAIT_STATE  = 2'b01,
                 FETCH_STATE = 2'b10,
                 INC_STATE   = 2'b11;

reg [1:0] current_state, next_state;

always @(posedge clk or posedge reset) begin
    if (reset) current_state <= RESET_STATE;
    else     current_state <= next_state;
end

always @* begin
    case (current_state)
        RESET_STATE: next_state = WAIT_STATE;
        WAIT_STATE:  next_state = coin_inserted ? FETCH_STATE : WAIT_STATE;
        FETCH_STATE: next_state = item_selected ? INC_STATE : FETCH_STATE;
        INC_STATE:   next_state = WAIT_STATE;
        default:     next_state = RESET_STATE;
    endcase
end

assign state = current_state;

endmodule

module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // State definitions
    localparam S0 = 2'b00,
               S1 = 2'b01,
               S2 = 2'b10,
               S3 = 2'b11;

    reg [1:0] current_state, next_state;

    // Sequential logic for state transitions and reset
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            current_state <= S0;
        end else begin
            current_state <= next_state;
        end
    end

    // Combinational logic for next state
    always @* begin
        case (current_state)
            S0: next_state = coin_inserted ? S1 : S0;
            S1: next_state = coin_inserted ? S2 : S1;
            S2: next_state = item_selected ? S3 : S2;
            S3: next_state = item_selected ? S1 : S3;
            default: next_state = S0;
        endcase
    end

    // Output the current state
    assign state = current_state;

endmodule

module vending_machine (
