module vending_machine (
    input clk, reset,
    input coin_inserted, item_selected,
    output [1:0] state
);

    // State definitions
    localparam START  = 2'b00;
    localparam STOP   = 2'b01;
    localparam RESET  = 2'b10;

    reg [1:0] state;

    // State transition logic
    always @(posedge clk or posedge reset) begin
        if (reset) begin
            state <= START;
        end else begin
            case (state)
                START: 
                    if (item_selected) state <= STOP;
                STOP: 
                    if (coin_inserted) state <= RESET;
                RESET: 
                    state <= START;
                default: 
                    state <= START; // Handle unexpected states
            endcase
        end
    end

    assign state = state;

endmodule

