wire [3:0][3:0] pp;
genvar i, j;
generate
    for (i = 0; i < 4; i = i + 1) begin : gen_i
        for (j = 0; j < 4; j = j + 1) begin : gen_j
            assign pp[i][j] = a[i] & b[j];
        end
    end
endgenerate

// Initialize carry signals for the first stage
wire [3:0][3:0] c1;
assign c1[0] = 1'b0;
assign c1[1] = pp[0][3] | pp[1][2] | pp[2][1] | pp[3][0];
assign c1[2] = pp[0][2] | pp[1][1] | pp[2][0];
assign c1[3] = pp[0][1] | pp[1][0];

// First carry-save adder stage (c1)
wire [3:0][3:0] sum1;
wire [3:0] c2;
genvar i;
generate
    for (i = 0; i < 4; i = i + 1) begin : stage1
        assign sum1[i] = pp[i][0] ^ c1[i] ^ 1'b0;
        assign c2[i] = pp[i][0] & c1[i];
    end
endgenerate

// Second carry-save adder stage (c2)
wire [3:0][3:0] sum2;
wire [3:0] c3;
generate
    for (i = 0; i < 4; i = i + 1) begin : stage2
        assign sum2[i] = sum1[i] ^ c2[i] ^ 1'b0;
        assign c3[i] = sum1[i] & c2[i];
    end
endgenerate

// Third carry-save adder stage (c3)
wire [3:0][3:0] sum3;
wire [3:0] c4;
generate
    for (i = 0; i < 4; i = i + 1) begin : stage3
        assign sum3[i] = sum2[i] ^ c3[i] ^ 1'b0;
        assign c4[i] = sum2[i] & c3[i];
    end
endgenerate

// Fourth stage: Combine remaining carry bits
assign out[7] = c4[3];
assign out[6] = c4[2] | sum3[3];
assign out[5] = c4[1] | sum3[2];
assign out[4] = c4[0] | sum3[1];
assign out[3] = sum3[0];
assign out[2] = sum3[1] ^ sum3[2];
assign out[1] = sum3[2] ^ sum3[3];
assign out[0] = sum3[3];

endmodule

