module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    // Generate derived encryption/decryption keys
    wire [3:0] d_k = KEY ^ data_in[3:0]; // XOR lower 4 bits of data_in with key
    wire [3:0] e_k = ~d_k;          // Invert derived key

    // Encrypt lower 4 bits using d_k, decrypt upper using e_k
    assign data_out[3:0] = data_in[3:0] ^ d_k;
    assign data_out[7:4] = data_in[7:4] ^ e_k;

