module feistel_cipher (
    input [7:0] data_in,
    output [7:0] data_out
);
    parameter KEY = 4'b1010; // Example key

    // Split input into nibbles
    wire [3:0] a_upper = data_in[7:4];
    wire [3:0] a_lower = data_in[3:0];

    // Function to apply modular addition with key
    function [3:0] add_key;
        input [3:0] a;
        begin
            add_key = a + KEY;
            // Adjust if beyond 15 (not possible with 4 bits, but for conceptual completeness)
            add_key = (add_key > 4'b1111) ? 4'b1111 : add_key;
        end
    endfunction

    // Compute summed nibbles
    wire [3:0] b_upper = add_key(a_upper);
    wire [3:0] b_lower = add_key(a_lower);

    // Concatenate to form output
    assign data_out = {b_upper, b_lower};

endmodule

