module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    wire [3:0] eq;
    wire [3:0] gt;
    wire [3:0] lt;
    wire no_borrow_in;

    // Equality bits (XNOR)
    assign eq[0] = ~(a[0] ^ b[0]);
    assign eq[1] = ~(a[1] ^ b[1]);
    assign eq[2] = ~(a[2] ^ b[2]);
    assign eq[3] = ~(a[3] ^ b[3]);

    // Greater than bits (a > b)
    assign gt[0] = ~b[0];
    assign gt[1] = ~b[1] & eq[0];
    assign gt[2] = ~b[2] & eq[1] & eq[0];
    assign gt[3] = ~b[3] & eq[2] & eq[1] & eq[0];

    // Less than bits (a < b)
    assign lt[0] = b[0];
    assign lt[1] = b[1] & eq[0];
    assign lt[2] = b[2] & eq[1] & eq[0];
    assign lt[3] = b[3] & eq[2] & eq[1] & eq[0];

    // Compute lt (all eq bits are 1)
    assign no_borrow_in = &eq;

    // Compute outputs
    assign gt = ~(gt[3] | (eq[3] & gt[2]) | (eq[3] & eq[2] & gt[1]) | (eq[3] & eq[2] & eq[1] & gt[0]));
    assign eq = ~(lt[3] | (eq[3] & lt[2]) | (eq[3] & eq[2] & lt[1]) | (eq[3] & eq[2] & eq[1] & lt[0]));
    assign lt = no_borrow_in;
endmodule

module comparator_4bit(input [3:0] a, input [3:0] b, output gt, eq, lt);
    // Declare wires for intermediate comparisons
    wire eq3, eq2, eq1, eq0;
    wire term1, term2, term3, term4;
    wire G3, G2, G1, G0;
    wire notG3, notG2, notG1, notG0;
    wire A3, A2, A1, A0;
    wire A3_and_A2, A3_and_A2_and_A1, A3_and_A2_and_A1_and_A0;

    // Equality comparison using XOR and AND gates
    xor(x1, a[3], b[3]);
    and(eq3, x1, x1);

    xor(x2, a[2], b[2]);
    and(eq2, x2, x2);

    xor(x3, a[1], b[1]);
    and(eq1, x3, x3);

    xor(x4, a[0], b[0]);
    and(eq0, x4, x4);

    // All-b equal when all XORs are 0
    and(term1, eq3, eq2);
    and(term2, term1, eq1);
    and(term3, term2, eq0);
    and(A3_and_A2_and_A1_and_A0, term3, term3); // A3_and_A2_and_A1_and_A0 is 1 if all equal

    // Determine eq (a > b)
    not(notG3, a[3]);
    and(G3, a[3], notG3);
    not(notG2, a[2]);
    and(G2, a[2], notG2);
    not(notG1, a[1]);
    and(G1, a[1], notG1);
    not(notG0, a[0]);
    and(G0, a[0], notG0);

    // eq is G3 or (G2 and higher bits equal) or ...
    notG3_A3_and_A2, notG2_A3_and_A2, notG1_A3_and_A2, notG0_A3_and_A2;
    and(notG3_A3_and_A2, notG3, A3_and_A2_and_A1_and_A0);
    and(notG2_A3_and_A2, notG2, A3_and_A2_and_A1);
    and(notG1_A3_and_A2, notG1, A3_and_A2_and_A1);
    and(notG0_A3_and_A2, notG0, A3_and_A2_and_A1);

    or(A3_and_A2, G3, notG3_A3_and_A2);
    or(A3_and_A2_and_A1, A3_and_A2, notG2_A3_and_A2);
    or(A3_and_A2_and_A1_and_A0, A3_and_A2_and_A1, notG1_A3_and_A2);

    // Determine lt (a < b)
    notG3_A3, notG2_A3, notG1_A3, notG0_A3;
    and(notG3_A3, notG3, A3_and_A2_and_A1_and_A0);
    and(notG2_A3, notG2, A3_and_A2_and_A1);
    and(notG1_A3, notG1, A3_and_A2_and_A1);
    and(notG0_A3, notG0, A3_and_A2_and_A1);

    or(G3, A3_and_A2);
    or(G2, A3_and_A2_and_A1);
    or(G1, A3_and_A2_and_A1_and_A0, notG1_A3);
    or(G0, G1, notG0_A3);

    // Compute outputs
    or(gt, G3, notG3_A3_and_A2, notG2_A3_and_A2, notG1_A3_and_A2, notG0_A3_and_A2);
    assign eq = A3_and_A2_and_A1_and_A0;
    assign lt = G0;
endmodule

