module priority_encoder_4to2 (
    input  [3:0] in,
    output [1:0] out,
    output       valid
);
    wire or_y1;

    // out[1] is high if in[2] or in[3] is high
    or(or_y1, in[2], in[3]);
    assign out[1] = or_y1;

    // out[0] is high if in[1] is high, or in[2] is high and in[0] is low
    wire not_y0_or;
    or(not_y0_or, in[0], in[1]);
    and(out[0], in[2], not_y0_or);

    // Enable signal valid is high if any bit in in is high
    or(valid, in[0], in[1], in[2], in[3]);

endmodule

