module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

  localparam [1:0] stateA = 2'b00,
                   stateB = 2'b01,
                   stateC = 2'b10,
                   stateD = 2'b11;

  reg [1:0] current_state, next_state;

  always @(posedge resetn) begin
    if (clk)
      current_state <= stateA;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      stateA: begin
        if (r[0])
          next_state = stateB;
        else if (r[1])
          next_state = stateC;
        else if (r[2])
          next_state = stateD;
        else
          next_state = stateA;
      end
      stateB: begin
        if (r[0])
          next_state = stateB;
        else if (r[1])
          next_state = stateC;
        else if (r[2])
          next_state = stateD;
        else
          next_state = stateB;
      end
      stateC: begin
        if (r[0])
          next_state = stateB;
        else if (r[1])
          next_state = stateC;
        else if (r[2])
          next_state = stateD;
        else
          next_state = stateC;
      end
      stateD: begin
        if (r[0])
          next_state = stateB;
        else if (r[1])
          next_state = stateC;
        else if (r[2])
          next_state = stateD;
        else
          next_state = stateD;
      end
      default: next_state = stateA;
    endcase
  end

  assign g = (current_state == stateD) ? 3'b111 :
             (current_state == stateC) ? 3'b100 :
             (current_state == stateB) ? 3'b011 :
             3'b000;

endmodule

