module TopModule (
  input clk,
  input resetn,
  input  [2:0] r,
  output [2:0] g
);

// State definitions
localparam [1:0] IDLE    = 2'b00,
                 RED1    = 2'b01,
                 YELLOW  = 2'b10,
                 RED2    = 2'b11;

reg [1:0] current_state, next_state;

// State register
always @(posedge resetn) begin
  if (clk)
    current_state <= IDLE;
  else
    current_state <= next_state;
end

// Next state logic
always @(*) begin
  case (current_state)
    IDLE:    next_state = r[0] ? RED1 : IDLE;
    RED1:    next_state = (r == 3'b011) ? YELLOW : RED1;
    YELLOW:  next_state = (r == 3'b111) ? RED2 : YELLOW;
    RED2:    next_state = (r == 3'b000) ? IDLE : RED2;
    default: next_state = IDLE;
  endcase
end

// Output logic
assign g = (current_state == IDLE)    ? 3'b000 :
                  (current_state == RED1)    ? 3'b100 :
                  (current_state == YELLOW)  ? 3'b010 :
                  (current_state == RED2)    ? 3'b110 :
                  3'b000;

endmodule

