module TopModule (
  input p1a,
  input p1b,
  input p1c,
  input p1d,
  output p1y,
  input p2a,
  input p2b,
  input p2c,
  input p2d,
  output p2y
);

  wire t1, t2, t3, t4;
  wire s1, s2, s3, s4;

  // Compute intermediate NAND terms for T
  nand(t1, p1a, p1b);
  nand(t2, t1, p1c);
  nand(t3, t2, p1d);
  nand(t4, t3, t3);  // Invert t3 using NAND

  // Compute intermediate NAND terms for S
  nand(s1, p2a, p2b);
  nand(s2, s1, p2c);
  nand(s3, s2, p2d);
  nand(s4, s3, s3);  // Invert s3 using NAND

  // Generate outputs using NAND of inverted intermediates
  nand(p1y, t4, t4);
  nand(p2y, s4, s4);

endmodule

module TopModule (
  input p1a,
  input p1b,
  input p1c,
  input p1d,
  input p1e,
  input p1f,
  output p1y,
  input p2a,
  input p2b,
  input p2c,
  input p2d,
  output p2y
);

  wire path_a = p1a & p1b & p1c;
  wire path_b = p1d & p1e & p1f;
  wire path_c = p2a & p2b & p2c & p2d;

  assign p1y = path_a | path_b;
  assign p2y = path_c | p1y;

endmodule

module TopModule (
  input p1a,
  input p1b,
  input p1c,
  input p1d,
  input p1e,
  input p1f,
  output p1y,
  input p2a,
  input p2b,
  input p2c,
  input p2d,
  output p2y
);

  wire c1, c2;

  assign c1 = (p1a & p1b) | (p1c & c1);
  assign c2 = (p1d & p1e) | (p1f & c1);

  assign p1y = c1;
  assign p2y = c2;

endmodule

