module TopModule (
  input a,
  input b,
  input sel_b1,
  input sel_b2,
  output out_assign,
  output reg out_always
);

  wire selected_data;

  // Combinational logic to select between a and b based on sel_b1 and sel_b2
  assign selected_data = (sel_b1 && !sel_b2) ? a :
                         (!sel_b1 && sel_b2) ? b :
                         1'b0;

  // Tri-state buffer to output selected_data when out_assign is high, else zero
  assign out_assign = out_always ? selected_data : 1'bz;
  assign out_always = out_assign ? 1'b1 : 1'b0;

endmodule

