module TopModule (
  input [7:0] code,
  output reg [3:0] out,
  output reg valid
);

  localparam [7:0] KEY_SET0 = 8'b11110000;
  localparam [7:0] KEY_SET1 = 8'b00001111;

  always @(*) begin
    valid = 1'b0;
    out = 4'b0000;

    if (code == KEY_SET0) begin
      out = 4'b1001;
    end else if (code == KEY_SET1) begin
      out = 4'b0110;
      valid = 1'b1;
    end else if (code != 8'b00000000) begin
      case (code)
        8'b00000001: out = 4'b1000;
        8'b00000010: out = 4'b0111;
        8'b00000100: out = 4'b0110;
        8'b00001000: out = 4'b1001;
        8'b00010000: out = 4'b0100;
        8'b00100000: out = 4'b0011;
        8'b01000000: out = 4'b0010;
        8'b10000000: out = 4'b0001;
        default: out = 4'b0000;
      endcase
    end
  end

endmodule

