module TopModule (
  input [7:0] a,
  input [7:0] b,
  output [7:0] s,
  output overflow
);

  wire [7:0] p;
  wire [7:0] g;
  wire [8:0] c;

  assign p = a ^ b;
  assign g = a & b;

  assign c[0] = 1'b0;

  assign c[1] = g[0] | (p[0] & c[0]);
  assign c[2] = g[1] | (p[1] & c[1]);
  assign c[3] = g[2] | (p[2] & c[2]);
  assign c[4] = g[3] | (p[3] & c[3]);
  assign c[5] = g[4] | (p[4] & c[4]);
  assign c[6] = g[5] | (p[5] & c[5]);
  assign c[7] = g[6] | (p[6] & c[6]);
  assign c[8] = g[7] | (p[7] & c[7]);

  assign s = p ^ c[7:0];
  assign overflow = c[8] ^ c[7];

endmodule

module TopModule (
  input [7:0] a,
  input [7:0] b,
  output [7:0] s,
  output overflow
);

  wire [7:0] P, G;
  wire [8:0] C;

  assign C[0] = 1'b0;

  // Generate Propagate and Generate signals with delays
  assign #1 P = a ^ b;
  assign #1 G = a & b;

  // Stage 1 Carry Lookahead
  wire [7:0] P1, G1;
  assign P1 = P;
  assign G1 = G;

  wire [7:0] C1;
  genvar i;
  generate
    for (i=0; i<8; i=i+1) begin: stage1
      assign C1[i] = G[i] | (P[i] & C[0]);
    end
  endgenerate

  // Stage 2 Carry Lookahead
  wire [7:0] P2, G2;
  assign P2 = P1;
  assign G2 = G1;

  wire [8:0] C2;
  assign C2[0] = C1[0];

  generate
    for (i=0; i<8; i=i+1) begin: stage2
      assign C2[i+1] = G2[i] | (P2[i] & C1[i]);
    end
  endgenerate

  // Stage 3 Carry Lookahead
  wire [7:0] P3, G3;
  assign P3 = P2;
  assign G3 = G2;

  wire [9:0] C3;
  assign C3[0] = C2[0];
  assign C3[1] = C2[1];

  generate
    for (i=0; i<8; i=i+1) begin: stage3
      assign C3[i+2] = G3[i] | (P3[i] & C2[i+1]);
    end
  endgenerate

  // Compute sum bits and final carry
  assign #1 s = P ^ C2;
  assign #1 overflow = C2[8];

endmodule

module TopModule (
  input [7:0] a,
