  nor(xnor_ab, a, b);
  nor(out_xor, xnor_ab, xnor_ab);

  // NOR gate: a NOR b using NOR
  nor(out_nand, a, b);

  // NAND gate: ~(a AND b) using NOR
  nor(nand_ab, a, b);
  nor(out_nor, nand_ab, nand_ab);

  // XNOR gate: a XNOR b using NOR
  nor(xnor_ab, a, b);
  nor(out_xnor, xnor_ab, xnor_ab);

  // AND gate: a AND b using NOR
  nor(and_temp, nor_a_b, nor_a_b);
