module TopModule (
  input [3:0] x,
  input [3:0] y,
  output [4:0] sum
);

  wire [3:0] P, G;
  wire c1, c2, c3, c4;

  assign P = x ^ y;
  assign G = x & y;

  assign c1 = G[0];
  assign c2 = G[1] | (P[1] & G[0]);
  assign c3 = G[2] | (P[2] & G[1]) | (P[2] & P[1] & G[0]);
  assign c4 = G[3] | (P[3] & G[2]) | (P[3] & P[2] & G[1]) | (P[3] & P[2] & P[1] & G[0]);

  assign sum[0] = P[0];
  assign sum[1] = P[1] ^ c1;
  assign sum[2] = P[2] ^ c2;
  assign sum[3] = P[3] ^ c3;
  assign sum[4] = c4;

endmodule

module TopModule (
  input [3:0] x,
  input [3:0] y,
  output [4:0] sum
);

  wire [3:0] p;
  wire [3:0] g;
  wire [3:0] carry;

  assign p = x ^ y;         // Propagate signals
  assign g = x & y;         // Generate signals

  // Carry Look-Ahead Logic
  assign carry[0] = g[0];                   // Initial carry-in is 0, so carry[0] = g0
  assign carry[1] = g[1] | (p[1] & g[0]);   // carry[1] = g1 | (p1 & g0)
  assign carry[2] = g[2] | (p[2] & g[1]) | (p[2] & p[1] & g[0]);
  assign carry[3] = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]);

  // Sum calculation using propagate and carry signals
  assign sum[0] = p[0];                 // sum[0] = p0 (since carry[0] is 0)
  assign sum[1] = p[1] ^ carry[0];      // sum[1] = p1 ^ carry[0]
  assign sum[2] = p[2] ^ carry[1];      // sum[2] = p2 ^ carry[1]
  assign sum[3] = p[3] ^ carry[2];      // sum[3] = p3 ^ carry[2]
  assign sum[4] = carry[3];             // carry-out is the MSB of the result

endmodule

module TopModule (
  input [3:0] x,
