                   S3 = 3'b011,
                   S4 = 3'b100;

  reg [2:0] current_state, next_state;

  // State register
  always @(posedge clk) begin
    if (reset)
      current_state <= S0;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      S0: next_state = w ? S1 : S0;
      S1: next_state = w ? S1 : S2;
      S2: next_state = w ? S3 : S0;
      S3: next_state = w ? S4 : S2;
      S4: next_state = w ? S1 : S2;
      default: next_state = S0;
    endcase
  end

  // Output logic
  assign z = (current_state == S4);

