module TopModule (
  input clk,
  input reset,
  input w,
  output z
);

  // Define states as binary values
  localparam [2:0] Zero = 3'b000,
                   One = 3'b001,
                   OneZero = 3'b010,
                   OneZeroOne = 3'b011,
                   OneZeroOneOne = 3'b100,
                   OneZeroOneOneOne = 3'b101;

  reg [2:0] current_state, next_state;

  // State register with synchronous reset
  always @(posedge clk) begin
    if (reset)
      current_state <= Zero;
    else
      current_state <= next_state;
  end

  // Next state logic based on current state and input
  always @(*) begin
    case (current_state)
      Zero:
        next_state = w ? One : Zero;
      One:
        next_state = w ? One : OneZero;
      OneZero:
        next_state = w ? OneZeroOne : Zero;
      OneZeroOne:
        next_state = w ? OneZeroOneOne : OneZero;
      OneZeroOneOne:
        next_state = w ? OneZeroOneOneOne : OneZero;
      OneZeroOneOneOne:
        next_state = w ? One : Zero;
      default:
        next_state = Zero;
    endcase
  end

  // Output is high only in the final state
  assign z = (current_state == OneZeroOneOneOne);

