  always @(*) begin
    case (state_reg)
      SAME: next_state = (a ^ b) ? DIFF : SAME;
      DIFF: next_state = DIFF;
      default: next_state = SAME;
    endcase
  end

  // State register
  always @(posedge clk) begin
    state_reg <= next_state;
