             STATE1 = 2'b01,
             STATE2 = 2'b10;

  reg [1:0] current_state, next_state;

  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= STATE0;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      STATE0: next_state = x ? STATE1 : STATE0;
      STATE1: next_state = x ? STATE2 : STATE0;
      STATE2: next_state = x ? STATE2 : STATE0;
      default: next_state = STATE0;
    endcase
  end

  assign z = (current_state == STATE1) ? x : ~x;

endmodule

