module TopModule (
  input clk,
  input in,
  input reset,
  output done
);
  reg [2:0] counter;
  reg [1:0] state, next_state;
  reg [2:0] max_count;

  // State definitions
  localparam IDLE = 2'b00;
  localparam RUN  = 2'b01;
  localparam WAIT = 2'b10;

  // State register
  always @(posedge clk) begin
    if (in)
      state <= IDLE;
    else
      state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (state)
      IDLE: next_state = (reset) ? RUN : IDLE;
      RUN:  next_state = WAIT;
      WAIT: next_state = (counter == max_count) ? IDLE : RUN;
      default: next_state = IDLE;
    endcase
  end

  // Max count determination
  always @(*) begin
    case (state)
      IDLE: max_count = 3'd1; // 2 cycles (0-1)
      RUN:  max_count = 3'd3; // 4 cycles (0-3)
      WAIT: max_count = 3'd6; // 7 cycles (0-6)
      default: max_count = 3'd1;
    endcase
  end

  // Counter logic
  always @(posedge clk) begin
    if (in)
      counter <= 3'd0;
    else if (state == RUN || state == WAIT)
      counter <= (counter == max_count) ? 3'd0 : counter + 1;
    else
      counter <= 3'd0;
  end

  // Output assignment
  assign done = (state == WAIT);

endmodule

