module TopModule (
  input a,
  input b,
  input c,
  input d,
  output out
);

  wire all_ones;
  wire not_x0, not_x1, not_x2, not_x3;
  wire term1, term2_part1, term2_part2, term2_OR, term2;

  // Calculate all_ones using AND gate
  assign all_ones = a & b & c & d;

  // Calculate NOT gates using NAND
  assign not_x0 = ~(a & a);
  assign not_x1 = ~(b & b);
  assign not_x2 = ~(c & c);
  assign not_x3 = ~(d & d);

  // Compute term1 (d == 0 and a == 1)
  assign term1 = ~(not_x3 & not_x0);

  // Compute term2_part1 (d == 0 and b == 0)
  assign term2_part1 = ~(not_x3 & not_x1);

  // Compute term2_part2 (c == 1 and a == 0)
  assign term2_part2 = ~(not_x2 & a);

  // Compute term2_OR (term2_part1 OR term2_part2)
  assign term2_OR = ~(term2_part1 & term2_part2);

  // Compute term2 (term2_OR and b)
  assign term2 = ~(term2_OR & b);

  // Combine term1 and term2 using OR gate
  assign out = ~(term1 & term2);

endmodule

