  and (term0, not_A2, not_A3);
  and (term1, not_A0, not_A3);
  and (term2, not_A0, not_A2);

  // Inverters for the intermediate terms
  not (not_term0, term0);
  not (not_term1, term1);
  not (not_term2, term2);

  // Final output (OR of the inverted terms)
  or (out, not_term0, not_term1, not_term2);

endmodule

