  parameter Mv_Dn = 2'b10;
  parameter op_st = 2'b11;

  reg [1:0] state, next_state;

  always @(posedge clk or posedge areset) begin
    if (areset) state <= IDLE;
    else state <= next_state;
  end

  always @(*) begin
    case (state)
      IDLE: begin
        if (ground) begin
          if (bump_right && !bump_left)
            next_state = Mv_Up;
          else if (!bump_right && bump_left)
            next_state = Mv_Dn;
          else
            next_state = IDLE;
        end
        else
          next_state = IDLE;
      end
      Mv_Up: next_state = (bump_left) ? op_st : Mv_Up;
      Mv_Dn: next_state = (bump_right) ? op_st : Mv_Dn;
      op_st: next_state = (ground) ? op_st : IDLE;
      default: next_state = IDLE;
    endcase
  end

  assign walk_left = (state == Mv_Up);
  assign walk_right = (state == Mv_Dn);
  assign aaah = (state != IDLE);

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  reg [1:0] current_state, next_state;
  localparam S_A      = 2'b00;
  localparam Moving_AB = 2'b01;
  localparam S_B      = 2'b10;
  localparam Moving_BA = 2'b11;

  // State register
  always @(posedge clk or posedge areset) begin
    if (areset)
      current_state <= S_A;
    else
      current_state <= next_state;
  end

  // Next state logic
  always @(*) begin
    case (current_state)
      S_A: begin
        next_state = (bump_left) ? Moving_AB : S_A;
      end
      Moving_AB: begin
        next_state = (ground) ? S_B : Moving_AB;
      end
      S_B: begin
        next_state = (bump_right) ? Moving_BA : S_B;
      end
      Moving_BA: begin
        next_state = (ground) ? S_A : Moving_BA;
      end
      default: next_state = S_A;
    endcase
  end

  // Output logic
  assign walk_left   = (current_state == S_A);
  assign walk_right   = (current_state == S_B);
  assign aaah = (current_state == Moving_AB || current_state == Moving_BA);

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  // State encoding
  localparam [1:0] IDLE = 2'b00,
                   PLAY = 2'b01,
                   WIN  = 2'b10,
                   LOSE = 2'b11;

  reg [1:0] current_state, next_state;

  // State transition logic
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= IDLE;
    end else begin
      current_state <= next_state;
    end
  end

  // Next state combinational logic
  always @(*) begin
    case (current_state)
      IDLE: next_state = bump_left ? PLAY : IDLE;
      PLAY: begin
        if (ground)
          next_state = WIN;
        else if (bump_right)
          next_state = LOSE;
        else
          next_state = PLAY;
      end
      WIN:  next_state = WIN;
      LOSE: next_state = LOSE;
      default: next_state = IDLE;
    endcase
  end

  // Output assignments
  assign walk_left = (current_state == IDLE);
  assign walk_right = (current_state == WIN);
  assign aaah = (current_state == IDLE || current_state == PLAY);

endmodule

module TopModule (
  input clk,
  input areset,
  input bump_left,
  input bump_right,
  input ground,
  output walk_left,
  output walk_right,
  output aaah
);

  // Define state parameters
  localparam [1:0] IDLE  = 2'b00,
                   COUNT = 2'b01,
                   LOAD  = 2'b10,
                   DONE  = 2'b11;

  reg [1:0] current_state, next_state;

  // Sequential logic for state transitions
  always @(posedge clk or posedge areset) begin
    if (areset) begin
      current_state <= IDLE;
    end
    else begin
      current_state <= next_state;
    end
  end

  // Combinational logic for next state
  always @(*) begin
    case (current_state)
      IDLE: next_state = bump_left ? COUNT : IDLE;
      COUNT: begin
        if (bump_right)
          next_state = ground ? LOAD : DONE;
        else
          next_state = COUNT;
      end
      LOAD: next_state = IDLE;
      DONE: next_state = IDLE;
      default: next_state = IDLE;
    endcase
  end

  // Output assignments
  assign walk_left = (current_state == IDLE);
  assign walk_right = (current_state == LOAD);
  assign aaah = (current_state == IDLE || current_state == LOAD);

endmodule

