module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

  reg [2:0] shift_reg;
  reg w_flag;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 3'b000;
      w_flag <= 1'b0;
    end else begin
      // Update shift register with new data input
      shift_reg <= {shift_reg[1:0], data};
      // Check if three consecutive identical bits are detected
      if (shift_reg == 3'b111 || shift_reg == 3'b000) begin
        w_flag <= 1'b1;
      end
    end
  end

  assign start_shifting = w_flag;

endmodule

module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

  reg [2:0] shift_reg;
  reg out_reg;

  always @(posedge clk) begin
    if (reset) begin
      shift_reg <= 3'b000;
      out_reg <= 1'b0;
    end else begin
      shift_reg <= {shift_reg[1:0], data};
      if (shift_reg == 3'b011 || shift_reg == 3'b100) begin
        out_reg <= 1'b1;
      end else if (shift_reg == 3'b000) begin
        out_reg <= 1'b0;
      end
    end
  end

  assign start_shifting = out_reg;

endmodule

module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

  reg sample0, sample1, sample2;
  reg coupled_reg;

  always @(posedge clk) begin
    if (reset) begin
      sample0 <= 1'b0;
      sample1 <= 1'b0;
      sample2 <= 1'b0;
      coupled_reg <= 1'b0;
    end else begin
      sample0 <= data;
      sample1 <= sample0;
      sample2 <= sample1;

      if (sample0 == 1'b0 && sample1 == 1'b0 && sample2 == 1'b0) begin
        coupled_reg <= 1'b0;
      end else if (sample0 == 1'b1 && sample1 == 1'b1 && sample2 == 1'b1) begin
        coupled_reg <= 1'b1;
      end
    end
  end

  assign start_shifting = coupled_reg;

endmodule

module TopModule (
