      shift_reg <= 3'b000;
      LedOut_reg <= 1'b0;
    end else begin
      // Update shift register with new button input
      shift_reg <= {shift_reg[1:0], data};

      // Detect stable press (000 for 3 cycles) and set LED
      if (shift_reg == 3'b000) begin
        LedOut_reg <= 1'b1;
      end
      // Detect release (100) and reset LED
      else if (shift_reg == 3'b100) begin
        LedOut_reg <= 1'b0;
      end
    end
  end

  assign start_shifting = LedOut_reg;

endmodule

module TopModule (
  input clk,
  input reset,
  input data,
  output start_shifting
);

  reg [2:0] shift_reg;
  reg alarm_reg;

  always @(posedge clk) begin
    if (data) begin
      shift_reg <= 3'b0;
      alarm_reg <= 1'b0;
    end else begin
      // Update shift register with current input
      shift_reg <= {shift_reg[1:0], reset};
      // Check if next state is '111' and current state isn't '111'
      if ({shift_reg[1:0], reset} == 3'b111 && !alarm_reg) begin
        alarm_reg <= 1'b1;
      end
    end
  end

  assign start_shifting = alarm_reg;

endmodule

