module TopModule (
  input [3:0] x,
  output logic f
);

  wire not_D3, not_D2, not_D1, not_D0;
  wire term1, term2, term3;

  // Inverters for D3, D2, D1, D0
  not (not_D3, x[3]);
  not (not_D2, x[2]);
  not (not_D1, x[1]);
  not (not_D0, x[0]);

  // Check for 7 (1111): D3 & D2 & D1 & D0
  and (term1, x[3], x[2], x[1], x[0]);

  // Check for 5 (1010): D3 & ~D2 & D0 & ~D1
  and (term2, x[3], not_D2, x[0], not_D1);

  // Check for 6 (1100): D3 & D2 & ~D1 & ~D0
  and (term3, x[3], x[2], not_D1, not_D0);

  // Combine terms to get output
  or (f, term1, term2, term3);

endmodule

