      case (state_stop)
        S_STOP_0: state_stop <= x ? S_STOP_1 : S_STOP_0;
        S_STOP_1: state_stop <= S_STOP_2;
        S_STOP_2: state_stop <= S_STOP_3;
        S_STOP_3: state_stop <= S_STOP_4;
        S_STOP_4: state_stop <= S_STOP_0;
        default: state_stop <= S_STOP_0;
      endcase
    end
  end

