module TopModule (
  input clk,
  input resetn,
  input x,
  input y,
  output f,
  output g
);

  localparam [2:0] IDLE = 3'd0,
                   S1 = 3'd1,
                   S2 = 3'd2,
                   S3 = 3'd3,
                   CORRECT = 3'd4,
                   MODE_CHANGE = 3'd5,
                   MODE_CHANGE_2 = 3'd6,
                   WRONG = 3'd7;

  reg [2:0] current_state, next_state;

  always @(posedge clk) begin
    if (resetn)
      current_state <= IDLE;
    else
      current_state <= next_state;
  end

  always @(*) begin
    case (current_state)
      IDLE: next_state = x ? S1 : IDLE;
      S1: begin
        if (x)
          next_state = y ? S2 : WRONG;
        else
          next_state = S1;
      end
      S2: begin
        if (x)
          next_state = y ? S3 : WRONG;
        else
          next_state = S2;
      end
      S3: next_state = x ? MODE_CHANGE : S3;
      CORRECT: next_state = x ? MODE_CHANGE_2 : CORRECT;
      MODE_CHANGE: next_state = MODE_CHANGE;
      MODE_CHANGE_2: next_state = MODE_CHANGE_2;
      WRONG: next_state = WRONG;
      default: next_state = IDLE;
    endcase
  end

  assign f = (current_state == MODE_CHANGE);
  assign g = (current_state == MODE_CHANGE_2);

endmodule

