    if (x)
      state_reg <= S0;
    else
      state_reg <= next_state;
  end

  always @(*) begin
    case (state_reg)
      S0: next_state = x ? S1 : S2;
      S1: next_state = x ? S0 : S2;
      S2: next_state = x ? S1 : S0;
