module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // Next state decoding logic
  assign B3_next = (state[9:7] == 3'b001);
  assign S_next = (state[9:7] == 3'b010);
  assign S1_next = (state[9:7] == 3'b011) & d;
  assign Count_next = (state[9:7] == 3'b100) | (state[8] & done_counting);
  assign Wait_next = (state[9:7] == 3'b101) | (state[7] & done_counting);
  assign done = state[6];
  assign counting = state[5];
  assign shift_ena = ack | (state[9:7] == 3'b000);

endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // One-hot decode state to done (state[9:6] maps to done-B3_next)
  assign done = state[9];
  assign counting = state[8];
  assign shift_ena = state[7];
  assign val_12 = state[6];

  // Compute each player's total using logical OR and AND gates
  assign B3_next = done | (done_counting & state[5]);
  assign S_next = counting | (ack & state[5]);
  assign S1_next = shift_ena | (d & state[5]);
  assign Count_next = done | (done_counting & state[4]);
  assign Wait_next = counting | (ack & state[4]);
  assign done = shift_ena | (d & state[4]);
  assign counting = done | (done_counting & state[3]);
  assign shift_ena = counting | (ack & state[3]);
  assign val_12 = shift_ena | (d & state[3]);

endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // Decode state into its components
  assign B3_next = state[0];
  assign done = state[1];
  assign counting = state[3];

  // Compute composite control signals using OR and AND operations
  assign S_next = B3_next | (d & done);
  assign S1_next = B3_next & d;
  assign Count_next = done_counting | (done & counting);
  assign Wait_next = done_counting & counting | state[2];
  assign shift_ena = ack | (done & counting);

endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // One-hot decoded current state signal
  wire [9:0] current_cpu = state[9:0];

  // 7-segment display segments (a to g)
  assign B3_next   = current_cpu[9]; // Segment a
  assign S_next = current_cpu[8]; // Segment b
  assign S1_next = current_cpu[7]; // Segment c
  assign Count_next  = current_cpu[6]; // Segment d
  assign Wait_next  = current_cpu[5]; // Segment e
  assign done = current_cpu[4]; // Segment f
  assign counting  = current_cpu[3]; // Segment g

  // Additional LED for CPU state
  assign shift_ena = ack;

  // Debug signals (example: CPU enable when d is active)
  assign S1_next = d & current_cpu[7];

endmodule

module TopModule (
  input d,
  input done_counting,
  input ack,
  input [9:0] state, // 10-bit one-hot current state
  output B3_next,
  output S_next,
  output S1_next,
  output Count_next,
  output Wait_next,
  output done,
  output counting,
  output shift_ena
);

  // Current state one-hot position assumptions (0-based):
  // B3_next: state[0], S_next: state[1], S1_next: state[2]
  // Count_next: state[3], Wait_next: state[4], done: state[5], counting: state[6]
  // shift_ena: state[7]

  assign B3_next = state[0];
  assign S_next = state[1];
  assign S1_next = state[2] & d;
  assign Count_next = state[3] | (state[4] & done_counting);
  assign Wait_next = state[4] | (state[5] & done_counting);
  assign done = state[5];
  assign counting = state[6];
  assign shift_ena = state[7] | (state[8] & ack) | (state[9] & ack);

endmodule

module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     wire [32:1] c;

     // Compute intermediate signal c
     assign c = { B[32:16], 1'b0, A[32:17] };

     // Register A and B with delay 21 and 22
     reg [32:1] reg_A;
     reg [32:1] reg_B;

     always @(A) begin
        #21 reg_A <= A;
     end

     always @(B) begin
        #22 reg_B <= B;
     end

     // Compute C32 as XOR of MSBs of registered A and B
     assign C32 = reg_A[32] ^ reg_B[32];

     // Assign output with delay 23
     assign #23 S = c;

endmodule

module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     wire [32:1] temp1, temp2;
     wire Cout;

     // Stage 1: Process A
     generate
         genvar i;
         for (i=1; i<=32; i=i+1) begin : stage1
             if (i==1) begin
                 if (A[i] === 1'b0) begin
                     S[i] <= 1'b1;
                     temp1[i] <= 1'b1;
                 end else begin
                     S[i] <= 1'b0;
                     temp1[i] <= 1'b0;
                 end
             end else if (i==32) begin
                 temp1[i] <= A[i] & temp1[i-1];
             end else begin
                 temp1[i] <= A[i] & temp1[i-1];
             end
         end
     endgenerate

     // Stage 2: Process B with intermediate carry
     assign Cout = temp1[32];

     generate
         for (i=1; i<=32; i=i+1) begin : stage2
             if (i==1) begin
                 if (B[i] === 1'b0) begin
                     S[i] <= 1'b1;
                     temp2[i] <= 1'b1;
                 end else begin
                     S[i] <= 1'b0;
                     temp2[i] <= 1'b0;
                 end
             end else if (i==32) begin
                 temp2[i] <= B[i] & Cout;
             end else begin
                 temp2[i] <= B[i] & Cout;
             end
         end
     endgenerate

     assign C32 = Cout;

endmodule

module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     wire [15:1] x_upper = A[32:18];
     wire [15:1] y_upper = B[32:18];
     wire [15:1] x_lower = A[17:1];
     wire [15:1] y_lower = B[17:1];

     wire [15:1] new_x_lower = x_lower & 16'hAAAA;
     wire [15:1] new_y_lower = y_lower & 16'hAAAA;

     assign S = {x_upper, y_upper, new_x_lower, new_y_lower};
     assign C32 = 1'b0;

endmodule

module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     reg [32:1] q_reg;

     always @(posedge S[1] or posedge A[32]) begin
         if (A[32]) begin
             q_reg <= 32'b1;
         end else begin
             q_reg <= {B[32], B[31:1], q_reg[31:1]};
         end
     end

     assign S = q_reg;
     assign C32 = q_reg[0];
endmodule

module adder_32bit(A,B,S,C32);
     input [32:1] A;
     input [32:1] B;
     output [32:1] S;
     output C32;

     // Concatenate upper 16 bits of A and B
     wire [31:0] upper_concat = {A[31:16], B[31:16]};

     // Flip the least significant bit of the concatenated result
     wire [31:0] flipped_concat = {upper_concat[31:1], ~upper_concat[0]};

     // Assign outputs
     assign S = {flipped_concat[31:16], A[15:1]};
     assign C32 = A[16];

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    wire [8:0] c;
    assign c[0] = cin;

    genvar i;
    generate
        for (i=0; i<8; i=i+1) begin: adder_stage
            wire p, g;
            assign p = a[i] ^ b[i];
            assign g = a[i] & b[i];
            assign c[i+1] = g | (p & c[i]);
            assign sum[i] = p ^ c[i];
        end
    endgenerate

    assign cout = c[8];

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

    // Compute propagate and generate signals for each bit
    wire [7:0] p, g;
    assign p = a ^ b;         // Propagate: XOR of a and b bits
    assign g = a & b;         // Generate: AND of a and b bits

    // Carry lookahead computation for each stage
    wire [8:0] c;
    assign c[0] = cin;                   // Initial carry-in (cin bit)

    genvar i;
    generate
        for (i=0; i<8; i=i+1) begin : carry_loookahead
            assign c[i+1] = g[i] | (p[i] & c[i]); // Carry equation
        end
    endgenerate

    // Compute sum bits and overflow
    assign sum = p ^ c[1:8];    // Sum using XOR with carry-in
    assign cout = c[8];               // Overflow is the final carry-out

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);

wire [8:0] st;
assign st = {1'b0, a} + {1'b0, (b ^ {8{cin}})} + cin;
assign sum = st[7:0];
assign cout = st[8];

endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);
    wire [7:0] b_adder;
    assign b_adder = b ^ {8{cin}}; // Extend cin to 8 bits and XOR with b

    // Half Adder for bits 0-3 (carry-in = 0)
    assign sum[0] = a[0] ^ b_adder[0];
    assign sum[1] = a[1] ^ b_adder[1];
    assign sum[2] = a[2] ^ b_adder[2];
    assign sum[3] = a[3] ^ b_adder[3];
    wire c1, c2, c3, c4_half;

    // Full Adder for bits 4-7
    assign sum[4] = a[4] ^ b_adder[4] ^ 1'b0;
    assign c1 = a[4] & b_adder[4];
    assign sum[5] = a[5] ^ b_adder[5] ^ c1;
    assign c2 = (a[5] & b_adder[5]) | (a[5] & c1) | (b_adder[5] & c1);
    assign sum[6] = a[6] ^ b_adder[6] ^ c2;
    assign c3 = (a[6] & b_adder[6]) | (a[6] & c2) | (b_adder[6] & c2);
    assign sum[7] = a[7] ^ b_adder[7] ^ c3;
    assign cout = c1 | c2 | c3;
endmodule

module adder_8bit(
    input [7:0] a, b, 
    input cin, 
    output [7:0] sum, 
    output cout);
    wire [8:0] C;
    assign C[0] = cin;

    genvar i;
    generate
        for (i=0; i<8; i=i+1) begin: adder_stage
            assign sum[i] = a[i] ^ b[i] ^ C[i];
            assign C[i+1] = (a[i] & b[i]) | (C[i] & (a[i] ^ b[i]));
        end
    endgenerate

    assign cout = C[8];
endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

wire [4:0] sum_temp = A + B + Cin;
wire [4:0] corrected_sum = sum_temp + ((sum_temp >= 10) ? 5'd6 : 5'd0);

assign Sum  = corrected_sum[3:0];
assign Cout = corrected_sum[4];

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
