    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);
    wire [3:0] g, p;
    wire c1, c2, c3, c4;

    // Generate and propagate signals
    assign g = A & B;
    assign p = A ^ B;

    // Compute carry signals
    assign c1 = g[0] | (p[0] & Cin);
    assign c2 = g[1] | (p[1] & g[0]) | (p[1] & p[0] & Cin);
    assign c3 = g[2] | (p[2] & g[1]) | (p[2] & p[1] & g[0]) | (p[2] & p[1] & p[0] & Cin);
    assign c4 = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]) | (p[3] & p[2] & p[1] & p[0] & Cin);

    // Compute sum bits
    assign Sum[0] = p[0] ^ Cin;
    assign Sum[1] = p[1] ^ c1;
    assign Sum[2] = p[2] ^ c2;
    assign Sum[3] = p[3] ^ c3;

    // Output carry
    assign Cout = c4;
endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    // Stage 1: Adders with 1-nanosecond delay
    wire [3:0] sum1;
    wire c1[4:1];
    assign #1 c1[1] = Cin;

    // Full Adder for bit 0
    assign sum1[0] = A[0] ^ B[0] ^ c1[1];
    assign c1[2] = (A[0] & B[0]) | (A[0] & c1[1]) | (B[0] & c1[1]);

    // Simple Adder for bit 1 (carry-in from stage 1)
    assign sum1[1] = A[1] ^ B[1] ^ c1[2];
    assign c1[3] = (A[1] & B[1]) | (A[1] & c1[2]) | (B[1] & c1[2]);

    // Simple Adder for bit 2 (carry-in from stage 1)
    assign sum1[2] = A[2] ^ B[2] ^ c1[3];
    assign c1[4] = (A[2] & B[2]) | (A[2] & c1[3]) | (B[2] & c1[3]);

    // Stage 2: Adders with 2-nanosecond delay
    wire [3:0] sum2;
    wire c2[4:1];
    assign #2 c2[1] = c1[4];

    // Full Adder for bit 0
    assign sum2[0] = sum1[0] ^ sum1[1] ^ c2[1];
    assign c2[2] = (sum1[0] & sum1[1]) | (sum1[0] & c2[1]) | (sum1[1] & c2[1]);

    // Simple Adder for bit 1 (carry-in from stage 2)
    assign sum2[1] = sum1[2] ^ B[3] ^ c2[2];
    assign c2[3] = (sum1[2] & B[3]) | (sum1[2] & c2[2]) | (B[3] & c2[2]);

    // Simple Adder for bit 2 (carry-in from stage 2)
    assign sum2[2] = sum1[3] ^ B[2] ^ c2[3];
    assign c2[4] = (sum1[3] & B[2]) | (sum1[3] & c2[3]) | (B[2] & c2[3]);

    // Stage 3: Adders with 3-nanosecond delay
    wire [3:0] sum3;
    wire c3[4:1];
    assign #3 c3[1] = c2[4];

    // Full Adder for bit 0
    assign sum3[0] = sum2[0] ^ sum2[1] ^ c3[1];
    assign c3[2] = (sum2[0] & sum2[1]) | (sum2[0] & c3[1]) | (sum2[1] & c3[1]);

    // Simple Adder for bit 1 (carry-in from stage 3)
    assign sum3[1] = sum2[2] ^ sum2[3] ^ c3[2];
    assign c3[3] = (sum2[2] & sum2[3]) | (sum2[2] & c3[2]) | (sum2[3] & c3[2]);

    // Simple Adder for bit 2 (carry-in from stage 3)
    assign sum3[2] = sum2[3] ^ B[3] ^ c3[3];
    assign c3[4] = (sum2[3] & B[3]) | (sum2[3] & c3[3]) | (B[3] & c3[3]);

    // Stage 4: Adders with 4-nanosecond delay
    wire [3:0] sum4;
    wire c4[4:1];
    assign #4 c4[1] = c3[4];

    // Full Adder for bit 0
    assign sum4[0] = sum3[0] ^ sum3[1] ^ c4[1];
    assign c4[2] = (sum3[0] & sum3[1]) | (sum3[0] & c4[1]) | (sum3[1] & c4[1]);

    // Simple Adder for bit 1 (carry-in from stage 4)
    assign sum4[1] = sum3[2] ^ sum3[3] ^ c4[2];
    assign c4[3] = (sum3[2] & sum3[3]) | (sum3[2] & c4[2]) | (sum3[3] & c4[2]);

    // Simple Adder for bit 2 (carry-in from stage 4)
    assign sum4[2] = sum4[0] ^ sum4[1] ^ c4[3];
    assign c4[4] = (sum4[0] & sum4[1]) | (sum4[0] & c4[3]) | (sum4[1] & c4[3]);

    // Full Adder for bit 3 (carry-in from stage 4)
    assign sum4[3] = sum4[2] ^ B[3] ^ c4[4];
    assign c4[5] = (sum4[2] & B[3]) | (sum4[2] & c4[4]) | (B[3] & c4[4]);

    // Output assignment
    assign Sum = sum4;
    assign Cout = c4[5];

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    // Stage 1: Adders for each bit with initial carry (0)
    wire [3:0] sum1;
    wire [3:0] carry1;

    assign carry1[0] = Cin; // Initial carry-in for LSB

    // Bit 0
    assign sum1[0] = A[0] ^ B[0] ^ carry1[0];
    assign carry1[1] = (A[0] & B[0]) | (A[0] & carry1[0]) | (B[0] & carry1[0]);

    // Bit 1
    assign sum1[1] = A[1] ^ B[1] ^ carry1[1];
    assign carry1[2] = (A[1] & B[1]) | (A[1] & carry1[1]) | (B[1] & carry1[1]);

    // Bit 2
    assign sum1[2] = A[2] ^ B[2] ^ carry1[2];
    assign carry1[3] = (A[2] & B[2]) | (A[2] & carry1[2]) | (B[2] & carry1[2]);

    // Bit 3 (MSB)
    assign sum1[3] = A[3] ^ B[3] ^ carry1[3];
    wire carry_out_stage1 = (A[3] & B[3]) | (A[3] & carry1[3]) | (B[3] & carry1[3]);

    // Stage 2: Correction for overflow (>=10)
    wire [3:0] sum2;
    wire [3:0] carry2;

    assign carry2[0] = 1'b0; // No carry from correction to MSB

    // Bit 0
    assign sum2[0] = sum1[0] - 1'b1; // Subtract 1 for correction
    assign carry2[1] = sum1[1] >= carry1[1]; // Adjust based on previous carry

    // Bit 1
    assign sum2[1] = sum1[1] - carry2[1];
    assign carry2[2] = sum1[2] >= carry2[1];

    // Bit 2
    assign sum2[2] = sum1[2] - carry2[2];
    assign carry2[3] = sum1[3] >= carry2[2];

    // Bit 3 (MSB)
    assign sum2[3] = sum1[3] - carry2[3];
    assign Cout = carry2[3]; // Final carry-out

    assign Sum = sum2;

endmodule

module adder_bcd (
    input  [3:0] A,   // First BCD number (0-9)
    input  [3:0] B,   // Second BCD number (0-9)
    input  Cin,       // Input carry
    output [3:0] Sum, // BCD sum (0-9)
    output Cout       // Output carry
);

    wire [3:0] sum_temp;
    wire [3:0] correction;
    wire [4:0] sum_total;

    // Step 1: Temp sum (A + B + Cin)
    assign sum_temp = A + B + Cin;

    // Step 2: Determine correction based on BCD check
    assign correction = (sum_temp > 9 || Cin) ? 4'd6 : 4'd0;

    // Step 3: Calculate final sum and carry
    assign sum_total = sum_temp + correction;

    // Step 4: Assign outputs
    assign Sum = sum_total[3:0];
    assign Cout = sum_total[4];

endmodule

