    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    // Compute unsigned result and carry-out
    wire [4:0] unsigned_result = A + B;
    assign A_equal = unsigned_result[4];
    assign A_greater = (unsigned_result[3] == 1'b0); // Check MSB for unsigned overflow

    // Compute two's complement result and carry-out
    wire [4:0] twos_complement_result = A + (~B) + 1'b1;
    assign A_less = twos_complement_result[4];
    assign A_greater = (twos_complement_result[3] == 1'b1); // Check MSB for signed overflow

endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    // Generate (G) and Propagate (P) signals for each bit
    wire [3:0] G = A & B;
    wire [3:0] P = A ^ B;

    // Carry Look-Ahead logic
    wire C0 = 1'b0; // Initial carry-in is 0
    wire C1 = G[0] | (P[0] & C0);
    wire C2 = G[1] | (P[1] & C1);
    wire C3 = G[2] | (P[2] & C2);
    wire C4 = G[3] | (P[3] & C3);

    // Sum calculation using XOR with carry
    wire [3:0] sum = {C4, P[3] ^ C3, P[2] ^ C2, P[1] ^ C1, P[0] ^ C0};

    // Assign outputs
    assign A_equal = sum[0];    // LSB of the sum
    assign A_greater = sum[1];    // Second bit of the sum
    assign A_less = C4;         // Carry-out from the MSB

endmodule

module comparator_4bit(
    input [3:0] A,   // First 4-bit input operand
    input [3:0] B,   // Second 4-bit input operand
    output A_greater, 
    output A_equal,   
    output A_less     
);

    // Generate and propagate signals for each bit (bit 0 to bit 3)
    wire [3:0] g, p;
    assign g = A & B;
    assign p = A ^ B;

    // Group generate (A_less) and propagate (A_equal) signals
    assign A_less = g[3] | (p[3] & g[2]) | (p[3] & p[2] & g[1]) | (p[3] & p[2] & p[1] & g[0]);
    assign A_equal = p[3] & p[2] & p[1] & p[0];

    // Compute A_greater using group generate and propagate
    assign A_greater = A_less | (A_equal & 1'b0);

endmodule

