module instr_reg (
    input clk,
    input rst,
    input [1:0] fetch,
    input [7:0] data,
    output [2:0] ins,
    output [4:0] ad1,
    output [7:0] ad2
);

reg [7:0] w0_reg, w1_reg, w2_reg;

always @(posedge clk) begin
    if (rst) begin
        w0_reg <= 8'b0;
        w1_reg <= 8'b0;
        w2_reg <= 8'b0;
    end else begin
        case (fetch)
            2'b00: begin
                w0_reg <= data;
                // w1 and w2 retain their values
            end
            2'b01: begin
                w1_reg <= data;
                // w0 and w2 retain their values
            end
            2'b10: begin
                w2_reg <= data;
                // w0 and w1 retain their values
            end
            default: begin
                // No write operation, retain values
            end
        endcase
    end
end

