module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// Synchronize button inputs to avoid metastability
	reg [3:0] button_sync;
	always @(posedge clk_a or negedge clk_b) begin
		if (!clk_b) begin
			button_sync <= 4'b0;
		end else begin
			button_sync <= {data_en, arstn, brstn, data_in[0]};
		end
	end

	// Delay switch inputs for additional stability
	reg [3:0] switch_delay;
	always @(posedge clk_a or negedge clk_b) begin
		if (!clk_b) begin
			switch_delay <= 4'b0;
		end else begin
			switch_delay <= {button_sync[3:1], data_in[3:1]};
		end
	end

	// Update output only when brstn is active
	always @(posedge clk_a or negedge clk_b) begin
		if (!clk_b) begin
			dataout <= 4'b0;
	 end else begin
		 if (brstn) begin
			  dataout <= switch_delay;
		 end
	 end
	end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

	// Synchronizer registers for each metastability input
	reg [3:0] cpu_rdy_sync;
	reg [3:0] bus_wreq_sync;
	reg [3:0] bus_ack_sync;

	// Synchronization process: Capture inputs on clk_a and propagate to next stage on clk_b
	always @(posedge clk_a or negedge arstn) begin
		if (!arstn) begin
			cpu_rdy_sync <= 4'b0;
			bus_wreq_sync <= 4'b0;
			bus_ack_sync  <= 4'b0;
		end else begin
			cpu_rdy_sync <= data_en;
			bus_wreq_sync <= brstn;
			bus_ack_sync  <= data_in;
		end
	end

	// Output update logic using synchronized values and enable
	always @(posedge clk_b or negedge arstn) begin
		if (!arstn) begin
			dataout <= 4'b0;
		end else if (clk_a) begin
			dataout <= bus_ack_sync;
		end
	end

endmodule

module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
