// Synchronize data_en and data_in to clk_a domain
always @(posedge clk_a or negedge arstn) begin
	if (!arstn) begin
		comm_sync_reg <= 4'b0;
		data_reg <= 4'b0;
	end
	else begin
		comm_sync_reg <= data_en;
		data_reg <= data_in;
	end
end

// Update dataout based on synchronized data_en
always @(posedge clk_a or negedge arstn) begin
	if (!arstn) begin
		dataout <= 4'b0;
	end
	else if (brstn) begin
		dataout <= comm_sync_reg;
	end
	else if (clk_b) begin
