		end else begin
			stage2 <= stage1;
		end
	end

	// Update dataout based on brstn and data_en
	always @(posedge clk_b or negedge arstn) begin
		if (!arstn) begin
			dataout <= 4'b0;
		end else begin
			if (brstn) begin
