module synchronizer(
	input 				clk_a	, 
	input 				clk_b	,   
	input 				arstn	,
	input				brstn   ,
	input		[3:0]	data_in	,
	input               data_en ,

	output reg  [3:0] 	dataout
);

    reg [3:0] data_reg;
    reg data_en_meta, data_en_sync;

    // Two-stage synchronizer for data_en in clk_a domain
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) begin
