            data_en_sync <= 1'b0;
        end else begin
            data_en_meta <= data_en;
            data_en_sync <= data_en_meta;
        end
    end

    // Capture data_in when brstn is asserted
    always @(posedge clk_a or negedge arstn) begin
        if (!arstn) begin
            data_reg <= 4'b0;
        end else begin
            if (brstn) begin
                data_reg <= data_in;
            end
        end
    end

    // Update dataout when synchronized enable is active
    always @(posedge clk_b or negedge arstn) begin
        if (!arstn) begin
            dataout <= 4'b0;
        end else begin
            if (data_en_sync) begin
                dataout <= data_reg;
            end
        end
    end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

parameter IDLE = 3'd0,
          START = 3'd1,
          SELECT = 3'd2,
          CHECK = 3'd3,
          LOAD = 3'd4;

reg [2:0] state, next_state;

always @(posedge CLK or posedge RST) begin
    if (RST) state <= IDLE;
    else state <= next_state;
end

always @(*) begin
    case (state)
        IDLE: next_state = IN ? START : IDLE;
        START: next_state = IN ? SELECT : START;
        SELECT: next_state = (~IN) ? CHECK : SELECT;
        CHECK: next_state = IN ? LOAD : CHECK;
        LOAD: next_state = IDLE;
        default: next_state = IDLE;
    endcase
end

always @(posedge CLK or posedge RST) begin
    if (RST) MATCH <= 1'b0;
    else MATCH <= (state == LOAD);
end

endmodule

module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

// Define states
parameter S0 = 3'b000,
          S1 = 3'b001,
          S2 = 3'b010,
          S3 = 3'b011,
          S4 = 3'b100;

reg [2:0] current_state, next_state;

// State register
always @(posedge CLK or posedge RST) begin
    if (RST)
        current_state <= S0;
    else
        current_state <= next_state;
end

// Next state logic
always @(*) begin
    case (current_state)
        S0: next_state = IN ? S1 : S0;
        S1: next_state = IN ? S1 : S2;
        S2: next_state = IN ? S1 : S3;
        S3: next_state = IN ? S4 : S0;
        S4: next_state = IN ? S1 : S2;
        default: next_state = S0;
    endcase
end

// Output logic
always @(*) begin
    MATCH = (current_state == S4);
end

endmodule

