module fsm(IN,MATCH,CLK,RST);
input IN,CLK,RST;
output reg MATCH;

parameter S0 = 3'b000,
          S1 = 3'b001,
          S2 = 3'b010,
          S3 = 3'b011,
          S4 = 3'b100;

reg [2:0] current_state, next_state;

always @(posedge CLK or posedge RST) begin
    if (RST) begin
        current_state <= S0;
    end else begin
        current_state <= next_state;
    end
end

always @(*) begin
    next_state = current_state;
    MATCH = 0;

    case (current_state)
        S0: begin
            if (IN) begin
                next_state = S1;
            end else begin
                next_state = S0;
            end
        end
        S1: begin
            if (IN) begin
                next_state = S1;
            end else begin
                next_state = S2;
            end
        end
        S2: begin
            if (IN) begin
                next_state = S3;
            end else begin
                next_state = S0;
            end
        end
        S3: begin
            if (IN) begin
                next_state = S0;
            end else begin
                next_state = S2;
            end
            MATCH = 1;
        end
        S4: begin
            next_state = S0;
            MATCH = 1;
        end
        default: next_state = S0;
    endcase
end

