output reg MATCH;

reg [1:0] state; // state[1]: up/down flag, state[0]: previous button state

parameter k1 = 2'b00,
          k2 = 2'b01,
          k3 = 2'b10,
          k4 = 2'b11;

reg [1:0] next_state;

// State register with asynchronous reset
always @(posedge CLK or posedge RST) begin
    if (RST) state <= k1;
    else state <= next_state;
end

// Next state logic
always @(*) begin
    next_state = state; // default: stay in current state
    if (IN) begin
        case(state)
            k1: next_state = k2;
            k2: next_state = k3;
            k3: next_state = k4;
            k4: next_state = k1;
            default: next_state = k1;
        endcase
    end
end

// Fly output logic (synchronous reset)
always @(posedge CLK or posedge RST) begin
    if (RST) MATCH <= 1'b0;
    else MATCH <= (state == k4) ? 1'b1 : 1'b0;
end

endmodule

module parallel2serial(
    input clk,
    input rst_n,
    input [3:0] d,
    output valid_out,
    output dout
);

reg [1:0] col_counter;
reg [3:0] row_counter;
reg keyboard_state;
reg key_out;

always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        col_counter <= 2'b00;
        row_counter <= 4'b0000;
        keyboard_state <= 1'b0;
        key_out <= 1'b0;
    end else begin
        // Increment column counter
        col_counter <= col_counter + 1;

        // Handle row_counter and keyboard_state
        if (col_counter == 2'b11) begin
            row_counter <= d;
            keyboard_state <= 1'b1;
        end else if (keyboard_state && (col_counter == 2'b11)) begin
            keyboard_state <= 1'b0;
        end

        // Determine key output
        if (keyboard_state) begin
            key_out <= d[col_counter];
        end else begin
            key_out <= 1'b0;
        end
    end
end

assign valid_out = keyboard_state;
assign dout = key_out;

endmodule

module parallel2serial(
