always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        counter <= 2'b00;
        shift_reg <= 4'b0000;
    end else begin
        case (counter)
            2'b00: begin
                counter <= counter + 1;
                shift_reg <= d;
            end
            2'b01: begin
                counter <= counter + 1;
                shift_reg <= {shift_reg[2:0], 1'b0};
            end
            2'b10: begin
                counter <= counter + 1;
                shift_reg <= {shift_reg[1:0], 2'b0};
            end
            2'b11: begin
                counter <= 2'b00;
                shift_reg <= d;
            end
            default: begin
                counter <= counter + 1;
                shift_reg <= d;
            end
        endcase
    end
end

assign valid_out = (counter == 2'b11);
assign dout = shift_reg[3];

endmodule

