    if (!rst_n) begin
        shift_reg <= 4'b0000;
    end else begin
        shift_reg <= {shift_reg[2:0], temp1};
    end
end

// Registered outputs
always @(posedge clk or negedge rst_n) begin
    if (!rst_n) begin
        valid_out <= 1'b0;
        dout <= 1'b0;
    end else begin
        valid_out <= (counter == 2'b10);
        dout <= shift_reg[3];
