module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

     // Define states
     localparam IDLE      = 3'd0,
                SETMIN    = 3'd1,
                INCMIN    = 3'd2,
                SETONOFF  = 3'd3,
                TOGGLEONOFF= 3'd4,
                SETTIME   = 3'd5,
                INCTIME   = 3'd6;

     reg [2:0] current_state, next_state;

     // State transition logic
     always @(posedge clk or negedge rst_n) begin
         if (!rst_n) begin
             current_state <= IDLE;
         end else begin
             current_state <= next_state;
         end
     end

     // Next state logic
     always @(*) begin
         case (current_state)
             IDLE:      next_state = data_in ? SETMIN : IDLE;
             SETMIN:    next_state = data_in ? SETMIN : INCMIN;
             INCMIN:    next_state = data_in ? SETONOFF : INCMIN;
             SETONOFF:  next_state = data_in ? TOGGLEONOFF : SETONOFF;
             TOGGLEONOFF: next_state = data_in ? SETTIME : TOGGLEONOFF;
             SETTIME:   next_state = data_in ? SETTIME : INCTIME;
             INCTIME:   next_state = data_in ? SETMIN : INCTIME;
             default:   next_state = IDLE;
         endcase
     end

     // Output logic
     assign sequence_detected = (current_state == INCTIME);

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

     // Define states
     localparam [2:0] IDLE_STATE  = 3'b000,
                      START_STATE = 3'b001,
                      DATA_STATE  = 3'b010,
                      PARITY_STATE= 3'b011,
                      STOP_STATE  = 3'b100;

     reg [2:0] state, next_state;

     // State transition (synchronous reset)
     always @(posedge clk or negedge rst_n) begin
         if (!rst_n)
             state <= IDLE_STATE;
         else
             state <= next_state;
     end

     // Next state logic
     always @(*) begin
         case (state)
             IDLE_STATE:   next_state = (~data_in) ? START_STATE : IDLE_STATE;
             START_STATE:  next_state = (data_in) ? DATA_STATE : START_STATE;
             DATA_STATE:   next_state = (data_in) ? PARITY_STATE : DATA_STATE;
             PARITY_STATE: next_state = (data_in) ? STOP_STATE : PARITY_STATE;
             STOP_STATE:   next_state = (data_in) ? IDLE_STATE : STOP_STATE;
             default:      next_state = IDLE_STATE;
         endcase
     end

     // Output is high only in START_STATE
     assign sequence_detected = (state == START_STATE);

endmodule

module sequence_detector(
     input  clk, 
     input  rst_n,
     input  data_in, 
     output sequence_detected				
     );

     localparam [2:0] 
         IDLE = 3'd0,
         P1   = 3'd1,
         P2   = 3'd2,
         P3   = 3'd3,
         G1   = 3'd4,
         G2   = 3'd5,
         G3   = 3'd6;

     reg [2:0] current_state, next_state;

     // State transition
     always @(posedge clk or negedge rst_n) begin
         if (!rst_n) 
            current_state <= IDLE;
         else 
            current_state <= next_state;
     end

     // Next state logic
     always @(*) begin
         case (current_state)
            IDLE: next_state = data_in ? P1 : IDLE;
            P1:   next_state = data_in ? P2 : IDLE;
            P2:   next_state = data_in ? P3 : IDLE;
            P3:   next_state = data_in ? P3 : G1;
            G1:   next_state = data_in ? G2 : IDLE;
            G2:   next_state = data_in ? G3 : IDLE;
            G3:   next_state = data_in ? G3 : IDLE;
            default: next_state = IDLE;
         endcase
     end

     // Output logic
     assign sequence_detected = (current_state == G1 || current_state == G2 || current_state == G3);

